-- Recepty se stejným názvem se přeskočí, takže skript jde spustit znovu.

do $$
declare rid bigint;
begin
  if not exists (select 1 from public.jid_recepty where nazev = 'Thajské kari (Kristína Nemčková)') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Thajské kari (Kristína Nemčková)', 'vareni', 4, 40, array['kuře','asijská']::text[], 'Kuře nakrájet na nudličky a marinovat v sójové omáčce. Zeleninu nakrájet (cibule na čtvrtky, papriky na kostky, mrkev a celer na kolečka, fazolky na 3–4 cm, pórek na kolečka). Uvařit jasmínovou rýži. Na woku opéct kešu, přidat maso a zprudka opékat s rybí omáčkou. Vmíchat kari pastu, chilli a ústřicovou omáčku, zalít horkým vývarem, dusit 10–15 min, přidat kokosové mléko. Zeleninu jen krátce povařit (max. minutu), vmíchat koriandr a bazalku, podávat s rýží.', 'https://madebykristina.cz/recepty/thajske-kari/') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'kuřecí prsa', 500, 'g', 'maso', 0), (rid, 'kuřecí vývar', 550, 'ml', 'trvanlive', 1), (rid, 'sójová omáčka', 2, 'lžíce', 'koreni', 2), (rid, 'ústřicová omáčka', 2, 'lžíce', 'koreni', 3), (rid, 'rybí omáčka', 1, 'lžíce', 'koreni', 4), (rid, 'žlutá kari pasta', 1, 'lžíce', 'koreni', 5), (rid, 'kokosové mléko', 200, 'ml', 'trvanlive', 6), (rid, 'cibule', 1, 'ks', 'zelenina', 7), (rid, 'mrkev', 1, 'ks', 'zelenina', 8), (rid, 'zelené fazolky mražené', 1, 'hrst', 'mrazene', 9), (rid, 'paprika červená', 1, 'ks', 'zelenina', 10), (rid, 'paprika žlutá', 1, 'ks', 'zelenina', 11), (rid, 'řapíkatý celer', 2, 'ks', 'zelenina', 12), (rid, 'pórek', 1, 'ks', 'zelenina', 13), (rid, 'kešu ořechy', 1, 'hrst', 'trvanlive', 14), (rid, 'thajská bazalka', 1, 'svazek', 'zelenina', 15), (rid, 'koriandr', 1, 'svazek', 'zelenina', 16), (rid, 'chilli', 1, 'ks', 'zelenina', 17), (rid, 'olej', 2, 'lžíce', 'trvanlive', 18), (rid, 'jasmínová rýže', 300, 'g', 'trvanlive', 19);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Thajské kari s kokosovým mlékem') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Thajské kari s kokosovým mlékem', 'vareni', 3, 35, array['kuře','asijská']::text[], 'Na kokosovém oleji orestovat cibuli a česnek, přidat kari pastu. Přidat kuřecí kousky a opéct. Přidat papriku, mrkev a fazolky, zalít kokosovým mlékem a vařit do měkka. Dochutit rybí (sójovou) omáčkou, cukrem, solí a pepřem. Podávat s jasmínovou rýží, ozdobit chilli, koriandrem a limetkou.', '') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'kuřecí prsa', 300, 'g', 'maso', 0), (rid, 'cibule', 1, 'ks', 'zelenina', 1), (rid, 'paprika červená', 1, 'ks', 'zelenina', 2), (rid, 'mrkev', 1, 'ks', 'zelenina', 3), (rid, 'zelené fazolky', 1, 'hrst', 'zelenina', 4), (rid, 'česnek', 1, 'stroužek', 'zelenina', 5), (rid, 'kokosové mléko', 400, 'ml', 'trvanlive', 6), (rid, 'červená kari pasta', 2, 'lžíce', 'koreni', 7), (rid, 'rybí omáčka', 1, 'lžíce', 'koreni', 8), (rid, 'třtinový cukr', 1, 'lžička', 'trvanlive', 9), (rid, 'kokosový olej', 1, 'lžíce', 'trvanlive', 10), (rid, 'jasmínová rýže', 250, 'g', 'trvanlive', 11), (rid, 'chilli', 1, 'ks', 'zelenina', 12), (rid, 'koriandr', 1, 'svazek', 'zelenina', 13), (rid, 'limetka', 1, 'ks', 'zelenina', 14);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Bleskové zelené kari') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Bleskové zelené kari', 'vareni', 4, 30, array['vege','asijská']::text[], 'Kokosové mléko rozmixovat s česnekem, zázvorem, chilli, zelenou částí jarní cibulky, citronovou trávou a stonky koriandru. Přelít do hrnce, mixér vypláchnout 100–150 ml vody a přidat. Krátce povařit, vmíchat cukr a rybí omáčku. Přidat brokolici, chřest a cukrový hrášek a vařit 4–5 min. Dochutit limetou, podávat s rýží, posypat sezamem.', 'https://www.apetitonline.cz/recept/bleskove-zelene-kari') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'kokosové mléko', 400, 'ml', 'trvanlive', 0), (rid, 'česnek', 3, 'stroužek', 'zelenina', 1), (rid, 'zázvor', 2, 'cm', 'zelenina', 2), (rid, 'zelené chilli', 3, 'ks', 'zelenina', 3), (rid, 'jarní cibulka', 5, 'ks', 'zelenina', 4), (rid, 'citronová tráva', 1, 'ks', 'zelenina', 5), (rid, 'koriandr', 1, 'svazek', 'zelenina', 6), (rid, 'cukr', 1, 'lžíce', 'trvanlive', 7), (rid, 'rybí omáčka', 2, 'lžíce', 'koreni', 8), (rid, 'brokolice', 250, 'g', 'zelenina', 9), (rid, 'zelený chřest', 0.5, 'svazek', 'zelenina', 10), (rid, 'cukrový hrášek', 180, 'g', 'zelenina', 11), (rid, 'limeta', 1, 'ks', 'zelenina', 12), (rid, 'rýže', 300, 'g', 'trvanlive', 13), (rid, 'černý sezam', 1, 'lžíce', 'trvanlive', 14);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Butter chicken s naanem') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Butter chicken s naanem', 'vareni', 4, 45, array['kuře','indická']::text[], 'Stehna nakrájet na kostky 2×2 cm a marinovat v jogurtu s kurkumou, solí, koriandrem, kmínem a garam masalou (ideálně přes noc). Maso po dávkách opéct na oleji s máslem a vyndat. V hrnci orestovat cibuli, česnek a zázvor, přidat koriandr, garam masalu a rajčata a rozmixovat. Dochutit cukrem a solí, vrátit kuře a vařit do měkka, na závěr vmíchat smetanu a máslo. Naan (nekynutý): smíchat mouku, cukr, sůl, prášek, olej a mléko, upéct na suché pánvi, potřít ghí s bylinkami. Podávat s basmati rýží.', 'https://madebykristina.cz/recepty/butter-chicken/') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'kuřecí stehna bez kosti', 800, 'g', 'maso', 0), (rid, 'bílý jogurt', 200, 'g', 'mlecne', 1), (rid, 'kurkuma', 2, 'lžička', 'koreni', 2), (rid, 'mletý koriandr', 2, 'lžička', 'koreni', 3), (rid, 'římský kmín', 1, 'lžička', 'koreni', 4), (rid, 'garam masala', 2, 'lžička', 'koreni', 5), (rid, 'máslo', 2, 'lžíce', 'mlecne', 6), (rid, 'česnek', 2, 'stroužek', 'zelenina', 7), (rid, 'cibule', 2, 'ks', 'zelenina', 8), (rid, 'zázvor', 1, 'lžíce', 'zelenina', 9), (rid, 'krájená rajčata', 2, 'plechovka', 'trvanlive', 10), (rid, 'smetana ke šlehání', 100, 'ml', 'mlecne', 11), (rid, 'hladká mouka', 120, 'g', 'trvanlive', 12), (rid, 'kypřicí prášek', 1, 'lžička', 'trvanlive', 13), (rid, 'mléko', 60, 'ml', 'mlecne', 14), (rid, 'ghí', 1, 'lžíce', 'mlecne', 15), (rid, 'koriandr', 1, 'svazek', 'zelenina', 16), (rid, 'basmati rýže', 300, 'g', 'trvanlive', 17);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Avokádový toast s uzeným lososem') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Avokádový toast s uzeným lososem', 'rychlovka', 3, 15, array['ryba','studené']::text[], 'Chléb opéct (nepovinné) a nechat vychladnout. Avokádo rozmačkat vidličkou se solí, pepřem, citronovou šťávou (a česnekem) nebo nakrájet na plátky. Natřít na chléb, navrch plátky okurky. Přidat uzeného lososa (asi 55 g na osobu) a nakládanou červenou cibuli. Ozdobit výhonky a olivovým olejem, podávat s klínkem citronu.', 'https://www.foolproofliving.com/') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'chléb (kváskový)', 6, 'krajíc', 'pecivo', 0), (rid, 'avokádo', 2, 'ks', 'zelenina', 1), (rid, 'uzený losos', 170, 'g', 'maso', 2), (rid, 'okurka salátová', 1, 'ks', 'zelenina', 3), (rid, 'červená cibule', 1, 'ks', 'zelenina', 4), (rid, 'citron', 1, 'ks', 'zelenina', 5), (rid, 'mikrobylinky / výhonky', 1, 'balení', 'zelenina', 6);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Brokolicový salát s čedarem') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Brokolicový salát s čedarem', 'vareni', 4, 35, array['vege','těstoviny','salát']::text[], 'Těstoviny uvařit, poslední 2–3 minuty přidat brokolici, na konci jarní cibulku, slít. Na pánvi na části oleje 2–3 min dusit papriku a vlašské ořechy. Odstavit, přidat zbylý olej, bazalku, cukr, sůl, pepř, ocet a citronovou šťávu. Těstoviny se zeleninou dát do mísy, přidat paprikovou směs a čedar (lžíci nechat). Promíchat, posypat zbytkem sýra a ozdobit bazalkou. Podávat teplý s ciabattou.', 'https://drive.google.com/file/d/1o_SSqLt6M1AHQCjmOow6VuH4SQjj0p-m/view') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'těstovinové mušličky', 200, 'g', 'trvanlive', 0), (rid, 'brokolice', 350, 'g', 'zelenina', 1), (rid, 'jarní cibulka', 3, 'ks', 'zelenina', 2), (rid, 'olivový olej', 4, 'lžíce', 'trvanlive', 3), (rid, 'paprika červená', 1, 'ks', 'zelenina', 4), (rid, 'vlašské ořechy', 60, 'g', 'trvanlive', 5), (rid, 'sušená bazalka', 1, 'lžička', 'koreni', 6), (rid, 'moučkový cukr', 1, 'lžička', 'trvanlive', 7), (rid, 'jablečný ocet', 2, 'lžíce', 'koreni', 8), (rid, 'citron', 1, 'ks', 'zelenina', 9), (rid, 'zralý čedar', 200, 'g', 'mlecne', 10), (rid, 'čerstvá bazalka', 1, 'svazek', 'zelenina', 11), (rid, 'ciabatta', 1, 'ks', 'pecivo', 12);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Chłodnik litewski (studená řepová polévka)') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Chłodnik litewski (studená řepová polévka)', 'vareni', 6, 90, array['vege','polévka','studené']::text[], 'Řepu zabalit do alobalu a péct na 200 °C asi 40 min (nebo koupit vařenou). Brambory uvařit, vychladit a rozpůlit. Okurky oloupat, nakrájet, posolit a nechat 15 min odkapat. Řepu oloupat a nakrájet na kostičky. Kefír prošlehat se zakysanou smetanou, vmíchat řepu, kopr, pažitku, polovinu okurek a ředkviček, dochutit solí, pepřem a octem. Vychladit (ideálně přes noc). Podávat na bramborách s vejcem naměkko, zbytkem okurek, ředkviček a bylinek.', '') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'červená řepa', 700, 'g', 'zelenina', 0), (rid, 'brambory', 700, 'g', 'zelenina', 1), (rid, 'okurky salátové', 450, 'g', 'zelenina', 2), (rid, 'kefír nebo podmáslí', 480, 'ml', 'mlecne', 3), (rid, 'zakysaná smetana', 240, 'g', 'mlecne', 4), (rid, 'kopr', 1, 'svazek', 'zelenina', 5), (rid, 'pažitka', 1, 'svazek', 'zelenina', 6), (rid, 'ředkvičky', 8, 'ks', 'zelenina', 7), (rid, 'vejce', 6, 'ks', 'mlecne', 8), (rid, 'ocet', 15, 'ml', 'koreni', 9), (rid, 'petržel hladkolistá', 1, 'svazek', 'zelenina', 10);
