  if not exists (select 1 from public.jid_recepty where nazev = 'Cizrna na paprice s pórkem') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Cizrna na paprice s pórkem', 'vareni', 4, 60, array['vege']::text[], 'Cizrnu namočit na 12 h a uvařit doměkka (nebo použít z konzervy). Na oleji opéct cibuli, přidat papriku a minutku opékat, zalít vývarem a povařit. Přidat třetinu cizrny a rozmixovat. Přidat zbytek cizrny a pórek a vařit, až pórek změkne. Vmíchat rostlinnou smetanu, dochutit solí, pepřem, chilli a citronem. Podávat s jasmínovou rýží.', '') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'cizrna sušená', 500, 'g', 'trvanlive', 0), (rid, 'cibule', 2, 'ks', 'zelenina', 1), (rid, 'pórek', 2, 'ks', 'zelenina', 2), (rid, 'mletá sladká paprika', 2, 'lžíce', 'koreni', 3), (rid, 'zeleninový vývar', 600, 'ml', 'trvanlive', 4), (rid, 'rýžová smetana', 200, 'ml', 'trvanlive', 5), (rid, 'olivový olej', 3, 'lžíce', 'trvanlive', 6), (rid, 'citron', 0.5, 'ks', 'zelenina', 7), (rid, 'mleté chilli', null, '', 'koreni', 8), (rid, 'jasmínová rýže', 500, 'g', 'trvanlive', 9);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Dhál z červené čočky s pečeným květákem a čapátí') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Dhál z červené čočky s pečeným květákem a čapátí', 'vareni', 4, 75, array['vege','indická']::text[], 'Květák promíchat s olejem a péct na 220 °C 15–20 min dozlatova. V hrnci opéct cibuli, přidat česnek, hořčičné semínko, kmín a zázvor. Přidat rajčata a čočku, zalít 500 ml vody a vařit 20–25 min. Osolit, vmíchat květák a polovinu koriandru. Čapátí: mouku smíchat s vodou, olejem a solí, nechat 20 min odpočinout, vyválet 12 placek a opékat na suché pánvi. Podávat s citronem a koriandrem.', 'https://www.apetitonline.cz/recept/dhal-z-cervene-cocky-a-peceneho-kvetaku-capati') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'květák', 1, 'ks', 'zelenina', 0), (rid, 'olej', 5, 'lžíce', 'trvanlive', 1), (rid, 'cibule', 1, 'ks', 'zelenina', 2), (rid, 'česnek', 3, 'stroužek', 'zelenina', 3), (rid, 'černé hořčičné semínko', 1, 'lžíce', 'koreni', 4), (rid, 'celý římský kmín', 1, 'lžíce', 'koreni', 5), (rid, 'zázvor', 30, 'g', 'zelenina', 6), (rid, 'krájená rajčata', 1, 'plechovka', 'trvanlive', 7), (rid, 'červená čočka', 250, 'g', 'trvanlive', 8), (rid, 'koriandr', 1, 'svazek', 'zelenina', 9), (rid, 'citron', 1, 'ks', 'zelenina', 10), (rid, 'hladká mouka', 260, 'g', 'trvanlive', 11);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Holandský řízek s bramborovými pusinkami a zelným salátem') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Holandský řízek s bramborovými pusinkami a zelným salátem', 'vareni', 4, 60, array['vepřové','česká']::text[], 'Bůček umlít a smíchat se sýrem, solí, pepřem, půlkou petržele, 1 vejcem a smetanou, dát na 30 min do lednice. Vytvarovat 4 řízky, obalit v mouce, vejci a strouhance s petrželí a citronovou kůrou a usmažit. Brambory uvařit, rozšťouchat s máslem, žloutkem, vejcem, solí a smetanou, vytlačit pusinky na plech a péct 12–15 min na 180 °C. Zelí nastrouhat, spařit, ochutit cukrem, octem, solí a pepřem, přidat opečenou slaninu s cibulí.', 'https://fresh.iprima.cz/holandsky-rizek-bramborove-pusinky') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'vepřový bůček bez kosti', 600, 'g', 'maso', 0), (rid, 'tvrdý sýr', 150, 'g', 'mlecne', 1), (rid, 'petržel hladkolistá', 1, 'svazek', 'zelenina', 2), (rid, 'vejce', 5, 'ks', 'mlecne', 3), (rid, 'smetana', 3, 'lžíce', 'mlecne', 4), (rid, 'hladká mouka', 50, 'g', 'trvanlive', 5), (rid, 'citron', 1, 'ks', 'zelenina', 6), (rid, 'strouhanka', 150, 'g', 'pecivo', 7), (rid, 'brambory', 750, 'g', 'zelenina', 8), (rid, 'máslo', 100, 'g', 'mlecne', 9), (rid, 'bílé zelí', 500, 'g', 'zelenina', 10), (rid, 'cibule', 1, 'ks', 'zelenina', 11), (rid, 'anglická slanina', 100, 'g', 'maso', 12), (rid, 'jablečný ocet', 3, 'lžíce', 'koreni', 13);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Kari s červenou čočkou a vejcem') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Kari s červenou čočkou a vejcem', 'vareni', 5, 50, array['vege','indická']::text[], 'Na oleji restovat cibuli 2–3 min. Přidat brambory na kostičky, kmín, papriku, kari, čočku a protlak a restovat 2 min. Vmíchat rajčata, vodu, sůl, pepř a česnek a vařit pod pokličkou 17–18 min. Vejce uvařit 8–9 min, oloupat a rozpůlit. Vmíchat citronovou kůru, špenát a petržel, dochutit citronem a krátce provařit. Podávat s půlkou vejce.', 'https://mandimu.cz/blogs/recepty/kari-s-cervenou-cockou-a-vejcem') returning id into rid;
    insert into public.jid_suroviny (recept_id, nazev, mnozstvi, jednotka, oddeleni, poradi) values (rid, 'olivový olej', 3, 'lžíce', 'trvanlive', 0), (rid, 'cibule', 100, 'g', 'zelenina', 1), (rid, 'brambory', 300, 'g', 'zelenina', 2), (rid, 'mletý římský kmín', 1, 'lžíce', 'koreni', 3), (rid, 'mletá sladká paprika', 1, 'lžíce', 'koreni', 4), (rid, 'kari koření', 1, 'lžíce', 'koreni', 5), (rid, 'červená čočka', 100, 'g', 'trvanlive', 6), (rid, 'rajčatový protlak', 2, 'lžíce', 'trvanlive', 7), (rid, 'krájená rajčata', 220, 'g', 'trvanlive', 8), (rid, 'česnek', 3, 'stroužek', 'zelenina', 9), (rid, 'vejce', 5, 'ks', 'mlecne', 10), (rid, 'citron', 1, 'ks', 'zelenina', 11), (rid, 'baby špenát', 1, 'hrst', 'zelenina', 12), (rid, 'petržel hladkolistá', 1, 'svazek', 'zelenina', 13);
  end if;
  if not exists (select 1 from public.jid_recepty where nazev = 'Koprová omáčka') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Koprová omáčka', 'vareni', 4, 60, array['vege','česká']::text[], 'Na másle zasmažit mouku do světlé jíšky, postupně metlou přilévat vývar. Osolit, opepřit, přivést k varu a vařit 30 min pod pokličkou. Přilít smetanu a 2 min povařit, stáhnout z plotny. Vmíchat nasekaný kopr (už nevařit), dochutit octem a cukrem, nakonec kousek másla. Podávat s bramborem a vejcem natvrdo (nebo s knedlíkem a hovězím).', 'https://fresh.iprima.cz/recepty/koprova-omacka') returning id into rid;
