  if not exists (select 1 from public.jid_recepty where nazev = 'Kuře na paprice s máslovými noky') then
    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Kuře na paprice s máslovými noky', 'vareni', 6, 60, array['kuře','česká']::text[], 'Kuře naporcovat, osolit a opéct na rozpuštěné slanině, vyndat. V tuku zesklovatět cibuli, zaprášit paprikou. Vrátit maso, zalít vývarem, přidat nové koření a dusit asi 40 min. Maso obrat z kostí. Z másla a mouky udělat kuličku, rozšlehat ve výpeku, povařit 10 min, vmíchat smetanu a přecedit na maso. Noky: z másla, vejce, soli, mléka a mouky těsto, odkrajovat do vroucí vody a vařit 8 min.', 'https://fresh.iprima.cz/recepty/kure-na-paprice-krok-za-krokem') returning id into rid;
