    insert into public.jid_recepty (nazev, typ, porce, cas_min, stitky, postup, odkaz) values ('Losos se zeleninou z jednoho plechu', 'vareni', 2, 40, array['ryba']::text[], 'Troubu předehřát na 180 °C. Rajčata rozpůlit a dát řezem dolů na plech, přidat mrkev na kolečka, pokapat olejem, osolit, opepřit a péct 15 min. Lososa osolit, opepřit a potřít pestem. Přidat na plech kůží dolů a péct dalších 10–12 min. Pesto: česnek, bazalka, parmazán, piniové oříšky a olej rozmixovat, osolit.', 'https://mandimu.cz/blogs/recepty/losos-se-zeleninou-z-jednoho-plechu') returning id into rid;
